// Church events (and a few historic ones, with a 5th field): name, year, reference, description. Shown as markers on the chart and in the
// timeline's Church lane; they are not sections, so the event column and its films are unchanged.
const CH_EV = [
  ['Sobór Nicejski I', 325, '', 'Po raz pierwszy w dziejach biskupi Wschodu i Zachodu zasiadają razem: w 325 r. zbierają się w Nicei, by rozstrzygnąć spór, który podzielił chrześcijan, czy Syn Boży jest prawdziwym Bogiem. Wobec nauki Ariusza wyznają, że Syn Boży jest „współistotny Ojcu”, „Bóg z Boga, Światłość ze Światłości”. To wyznanie, rozwinięte w Konstantynopolu, chrześcijanie Wschodu i Zachodu wspólnie odmawiają w Credo do dziś.'],
  ['Wielka schizma', 1054, '', 'Chrześcijański Wschód i Zachód, greckie i łacińskie dziedzictwo jednej wiary, przez wieki oddalają się od siebie, aż w 1054 r. legaci papiescy i patriarcha Konstantynopola obkładają się wzajemnie ekskomuniką. Rozłam nie został jeszcze przezwyciężony, lecz od 1965 r., gdy Paweł VI i patriarcha Atenagoras oddali te ekskomuniki w niepamięć, papieże i patriarchowie wspólnie modlą się o pojednanie.'],
  ['Sobór Trydencki', 1545, '', 'Przez osiemnaście lat, z przerwami, biskupi obradują w alpejskim Trydencie nad odpowiedzią na reformację. Sobór jasno wykłada naukę o łasce, sakramentach i Piśmie Świętym, a zarazem podejmuje odnowę od wewnątrz: zakłada seminaria dla przyszłych kapłanów, przygotowuje Katechizm Rzymski i mszał, który przez cztery stulecia jednoczy modlitwę Kościoła. Z tej odnowy wyrastają święci, jak Karol Boromeusz, i nowa fala misji.'],
  ['Sobór Watykański II', 1962, '', 'Według przekazu św. Jan XXIII, zwołując sobór, mówił, że trzeba otworzyć okna Kościoła, by wpuścić świeże powietrze. W latach 1962–1965 ponad dwa tysiące biskupów odnawia liturgię, wprowadzając języki narodowe, przypomina, że każdy ochrzczony jest powołany do świętości, i otwiera Kościół na dialog z innymi chrześcijanami, religiami i światem współczesnym. Jego dokumenty, jak „Lumen gentium” i „Gaudium et spes”, kształtują życie Kościoła do dziś.'],
  // Historic (non-Church) events carry the line key of their people as a 5th field.
  ['Rewolucja francuska', 1789, '', 'Pod hasłami wolności, równości i braterstwa Francja obala dawny porządek, a w 1792 r. upada monarchia. Rewolucja podporządkowuje jednak Kościół państwu i rozpętuje prześladowania, w których giną tysiące duchownych i wiernych. Wielu z nich Kościół czci dziś jako męczenników.', 'jap'],
  ['Septuaginta', -250, '', 'W Aleksandrii, wielkim ośrodku nauki, Żydzi zaczynają przekładać swoje święte Księgi na grekę, wspólny język ówczesnego świata, a dzieło to trwa przez kilka pokoleń. Tradycja mówi o siedemdziesięciu dwóch tłumaczach, stąd nazwa Septuaginta. W tym przekładzie Biblię czytali pierwsi chrześcijanie i często cytują go autorzy Nowego Testamentu.', 'jap']
];

