// Figures: name, internal year, role, description, reference, line, optional circle letter.
const FIG = [
  ['Adam', am(0), 'Pierwszy człowiek', 'Pierwszy człowiek, w którym Biblia widzi cały rodzaj ludzki: jego hebrajskie imię oznacza zarazem „człowieka” i „ludzkość”. Umieszczony przez Boga w ogrodzie Eden, przez nieposłuszeństwo traci raj, lecz nie traci nadziei, bo Bóg już wtedy zapowiada zwycięstwo nad złem (Rdz 3,15). Chrześcijanie nazywają Chrystusa „nowym Adamem”, który otwiera ludziom drogę powrotu do Boga.', 'Rdz 1-3', 'sem'],
  ['Henoch', am(987), 'Chodził z Bogiem', 'Siódmy patriarcha od Adama, o którym Pismo mówi najpiękniej, jak można powiedzieć o człowieku: „żył w przyjaźni z Bogiem, a następnie zniknął, bo zabrał go Bóg” (Rdz 5,24). Jako jedyny w tym rodowodzie nie umiera zwyczajnie, a List do Hebrajczyków stawia go wśród wzorów wiary, która podoba się Bogu (Hbr 11,5).', 'Rdz 5,24', 'sem'],
  ['Noe', am(1656), 'Budowniczy arki', 'Sprawiedliwy w zepsutym pokoleniu, który z posłuszeństwem i ufnością wznosi arkę i ocala w niej rodzinę oraz wszelkie stworzenia. Po potopie Bóg zawiera z nim przymierze obejmujące całą ludzkość, a jego znakiem staje się tęcza. Dla chrześcijan arka jest obrazem Kościoła, który bezpiecznie niesie ludzi przez fale dziejów.', 'Rdz 6-9', 'sem'],
  ['Nimrod', am(1720), 'Dzielny myśliwy', 'Biblia nazywa go „pierwszym mocarzem na ziemi” i „dzielnym myśliwym przed Panem”. Zakłada królestwo w krainie Szinear, z miastami Babel, Erek i Akkad. Józef Flawiusz widział w nim inicjatora budowy wieży Babel, obrazu ludzkiej pychy, a jego imię przetrwało w przysłowiu o wielkich łowcach.', 'Rdz 10,8-10', 'ham'],
  ['Abraham', -1825, 'Ojciec narodów', 'Patriarcha, który na Boże wezwanie opuszcza Charan i wyrusza w nieznane, a Bóg zmienia mu imię z Abram na Abraham, „ojciec mnóstwa narodów”. Wbrew nadziei ufa obietnicy i w starości otrzymuje syna Izaaka, dlatego św. Paweł nazywa go ojcem wszystkich wierzących (Rz 4,11). Czczą go żydzi, chrześcijanie i muzułmanie, a Kanon Rzymski wspomina go jako „naszego patriarchę”.', 'Rdz 12', 'sem'],
  ['Izaak', -1800, 'Syn obietnicy', 'Syn obietnicy, którego Abraham i Sara doczekali się w podeszłym wieku; jego imię wyraża radość, jaką narodziny dziecka sprawiły długo czekającym rodzicom (Rdz 21,6). Ocalony na górze Moria, gdy Bóg powstrzymał rękę ojca, poślubia Rebekę i zostaje ojcem bliźniąt, Ezawa i Jakuba. Bóg przedstawia się odtąd jako „Bóg Abrahama, Izaaka i Jakuba”.', 'Rdz 21', 'sem'],
  ['Jakub', -1740, 'Izrael', 'Syn Izaaka i Rebeki, młodszy z bliźniąt, którego droga wiedzie od podstępu do błogosławieństwa. W Betel śni o drabinie łączącej ziemię z niebem, a po nocnej walce nad potokiem Jabbok otrzymuje od Boga nowe imię, Izrael, które przejmie cały naród. Jego dwunastu synów daje początek dwunastu pokoleniom Izraela.', 'Rdz 25-50', 'sem'],
  ['Józef', -1620, 'Zarządca Egiptu', 'Ukochany syn Jakuba, sprzedany przez zazdrosnych braci do Egiptu, którego droga prowadzi z więzienia na dwór faraona. Dzięki mądrości i darowi tłumaczenia snów zostaje zarządcą kraju i ratuje przed głodem Egipt oraz własną rodzinę. Braciom, którzy go skrzywdzili, przebacza słowami: „Wy zamierzaliście wyrządzić mi zło, Bóg jednak zamierzył to jako dobro” (Rdz 50,20).', 'Rdz 37-50', 'sem'],
  ['Mojżesz', -1250, 'Prawodawca', 'Przywódca i prawodawca Izraela, który jako niemowlę ocalał z wód Nilu i wychował się na dworze faraona, a przy płonącym krzewie usłyszał od Boga Jego imię. Prowadzi lud z niewoli ku wolności, a na górze Synaj otrzymuje Dziesięć Przykazań, fundament przymierza. Umiera na górze Nebo, oglądając z daleka Ziemię Obiecaną, a w Ewangelii ukazuje się obok Jezusa na górze Przemienienia.', 'Wj 3-20', 'sem'],
  ['Jozue', -1210, 'Zdobywca Kanaanu', 'Sługa i następca Mojżesza, który przeprowadza Izraela przez Jordan do Ziemi Obiecanej i rozdziela ją między pokolenia. Jego hebrajskie imię, Jehoszua, znaczy „Pan zbawia”, a w greckiej formie brzmi tak samo jak imię Jezusa. U kresu życia stawia lud przed wyborem i sam daje przykład: „Ja i mój dom służyć będziemy Panu” (Joz 24,15).', 'Joz 3', 'sem'],
  ['Debora', -1125, 'Sędzia i prorokini', 'Prorokini i sędzia Izraela, która pod palmą między Ramą a Betel rozsądza spory ludu (Sdz 4,5). Gdy Kananejczycy uciskają kraj, wzywa wodza Baraka do walki i idzie razem z nim. Po zwycięstwie nad Syserą śpiewa pieśń (Sdz 5), uznawaną za jeden z najstarszych utworów Biblii.', 'Sdz 4-5', 'sem'],
  ['Samson', -1075, 'Sędzia', 'Sędzia Izraela i nazirejczyk poświęcony Bogu od łona matki, którego niezwykła siła była związana ze ślubem nieobcinania włosów. Zdradzony przez Dalilę, oślepiony i upokorzony przez Filistynów, w ostatniej modlitwie odzyskuje siłę. List do Hebrajczyków wymienia go wśród bohaterów wiary (Hbr 11,32).', 'Sdz 13-16', 'sem'],
  ['Saul', -1050, 'Pierwszy król Izraela', 'Izrael prosi o króla, „tak jak to jest u innych narodów” (1 Sm 8,5), a prorok Samuel namaszcza Saula z pokolenia Beniamina, który „o głowę przewyższał cały lud”. Odważny wojownik z czasem przestaje słuchać Boga, a jego dramat kończy się śmiercią na górze Gilboa. Dawid opłakuje go i Jonatana pieśnią: „Jakże padli bohaterowie!” (2 Sm 1,19).', '1 Sm 10', 'sem'],
  ['Dawid', -1000, 'Król Izraela', 'Najmłodszy syn Jessego z Betlejem, pasterz wybrany przez Boga, który „patrzy na serce” (1 Sm 16,7). Pokonuje Goliata, zostaje królem Izraela i czyni Jerozolimę stolicą. Upada w grzechu, lecz umie żałować, a tradycja przypisuje mu wiele psalmów, w tym psalm skruchy, Miserere (Ps 51). Bóg obiecuje, że jego dynastia przetrwa na wieki, dlatego Jezus nazywany jest „Synem Dawida”.', '2 Sm 5', 'sem'],
  ['Salomon', -960, 'Budowniczy świątyni', 'Gdy Bóg pozwala mu prosić, o co zechce, młody król prosi nie o bogactwo ani długie życie, lecz o „serce pełne rozsądku do sądzenia ludu” (1 Krl 3,9). Jego mądrość staje się przysłowiowa, jak świadczy sąd nad dwiema matkami i wizyta królowej Saby, a w Jerozolimie wznosi Bogu świątynię. Tradycja przypisuje mu Księgę Przysłów, Koheleta i Pieśń nad Pieśniami.', '1 Krl 6', 'sem'],
  ['Eliasz', -860, 'Prorok', 'Ognisty prorok Izraela, który na górze Karmel ukazuje moc prawdziwego Boga wobec proroków Baala. Na Horebie odkrywa jednak, że Bóg nie przychodzi w wichrze, trzęsieniu ziemi ani w ogniu, lecz w „szmerze łagodnego powiewu” (1 Krl 19,12). Uniesiony do nieba w wichrze, w Ewangelii ukazuje się obok Jezusa na górze Przemienienia.', '1 Krl 18', 'sem'],
  ['Izajasz', -742, 'Prorok', 'Prorok z Jerozolimy, który w świątyni ogląda chwałę Pana i słyszy wołanie serafinów: „Święty, Święty, Święty” (Iz 6,3), powtarzane dziś w każdej Mszy. Zapowiada Emmanuela, którego pocznie Panna, i Sługę Pańskiego cierpiącego za grzechy innych, tak że św. Hieronim nazwał go raczej ewangelistą niż prorokiem.', 'Iz 6,1', 'sem'],
  ['Ezechiasz', -715, 'Król Judy', 'Król Judy, który po latach bałwochwalstwa swego ojca oczyszcza świątynię i przywraca obchody Paschy. Gdy wojska asyryjskie oblegają Jerozolimę, idzie za radą proroka Izajasza i zawierza miasto Bogu, a Jerozolima ocala.', '2 Krl 18-19', 'sem'],
  ['Daniel', -605, 'Prorok w Babilonie', 'Młody Judejczyk uprowadzony do Babilonu, który na obcym dworze pozostaje wierny Bogu, nawet gdy czeka go jaskinia lwów, i wychodzi z niej nietknięty. W jego wizji pojawia się „ktoś podobny do Syna Człowieczego” (Dn 7,13); tym właśnie imieniem najczęściej nazywał siebie Jezus.', 'Dn 1', 'sem'],
  ['Cyrus', -538, 'Król Persji', 'Twórca perskiego imperium, który w 539 p.n.e. zdobywa Babilon i otwiera wygnańcom drogę do domu, pozwalając Żydom wrócić do Jerozolimy i odbudować świątynię. Księga Izajasza nazywa tego pogańskiego władcę „pomazańcem” Pana, narzędziem w ręku Boga, który prowadzi dzieje (Iz 45,1).', 'Ezd 1', 'jap'],
  ['Estera', -480, 'Królowa Persji', 'Młoda Żydówka, królowa Persji u boku króla Aswerusa, która staje przed wyborem, gdy jej ludowi grozi zagłada zaplanowana przez Hamana. Wbrew dworskiemu prawu, gotowa oddać życie, wchodzi nieproszona do króla i ocala swój naród. Na pamiątkę tego ocalenia Żydzi obchodzą radosne święto Purim.', 'Est 4-8', 'sem'],
  ['Nehemiasz', -445, 'Namiestnik', 'Podczaszy perskiego króla Artakserksesa, który na wieść o zrujnowanej Jerozolimie płacze i modli się, a potem prosi władcę o pozwolenie na odbudowę miasta. Jako namiestnik Judy odbudowuje z ludem mury w 52 dni, gdy budowniczowie jedną ręką pracują, a w drugiej trzymają broń (Ne 6,15). Prowadzi lud do uroczystego odnowienia przymierza z Bogiem.', 'Ne 2-6', 'sem'],
  ['Jan Chrzciciel', -6, 'Poprzednik', 'Syn Zachariasza i Elżbiety, krewny Jezusa i ostatni z proroków, który nad Jordanem wzywa do nawrócenia i chrzci, także samego Jezusa. Wskazuje na Niego słowami „Oto Baranek Boży” (J 1,29), powtarzanymi w każdej Mszy Świętej, i oddaje życie za wierność prawdzie.', 'Łk 1', 'chu'],
  ['Jezus', -5, 'Chrystus', '„Tak Bóg umiłował świat, że Syna swego Jednorodzonego dał” (J 3,16): w Jezusie, Synu Bożym i Synu Maryi, Bóg staje się jednym z nas. Uzdrawia, przebacza, zasiada do stołu z grzesznikami i uczy modlitwy „Ojcze nasz”, a przez śmierć na krzyżu i zmartwychwstanie otwiera każdemu człowiekowi drogę do Boga.', 'Mt 2; Łk 2', 'chu'],
  ['Piotr', 30, 'Apostoł', 'Rybak z Galilei, któremu Jezus nadaje imię Kefas, czyli Skała, i na nim buduje swój Kościół (Mt 16,18). Po zmartwychwstaniu trzykrotnie słyszy: „Paś owce moje” (J 21,15-17), a od dnia Zesłania Ducha Świętego staje się pasterzem pierwszej wspólnoty, który ją umacnia, jednoczy i prowadzi. Życie oddaje jako męczennik w Rzymie, a jego następcami są papieże.', 'Mt 16,18; J 21,15-17', 'chu'],
  ['Paweł', 35, 'Apostoł', 'Żyd z Tarsu i uczeń faryzeuszów, który z prześladowcy chrześcijan, po spotkaniu ze zmartwychwstałym Jezusem pod Damaszkiem, staje się Apostołem Narodów. Jako misjonarz przemierza świat rzymski i zakłada wspólnoty od Azji Mniejszej po Grecję, a jako pierwszy wielki teolog Kościoła wykłada w listach tajemnicę Chrystusa, łaski i miłości (1 Kor 13). Życie oddaje jako męczennik w Rzymie.', 'Dz 9-28', 'chu'],
  ['Konstantyn', 313, 'Cesarz rzymski', 'Po trzech stuleciach prześladowań chrześcijanie mogą wreszcie wyznawać wiarę jawnie: w 313 r. Konstantyn wraz z Licyniuszem ogłasza edykt mediolański. Cesarz zwołuje Sobór Nicejski i zakłada nad Bosforem Konstantynopol, a chrzest przyjmuje dopiero u kresu życia. Kościoły Wschodu czczą go jako świętego „równego apostołom”.', '', 'jap'],
  ['Marcin Luter', 1517, 'Reformator', 'Augustianin i profesor teologii w Wittenberdze, który, dręczony pytaniem o łaskawego Boga, odkrywa w Liście do Rzymian zbawienie z łaski przez wiarę. Jego 95 tez z 1517 r. daje początek reformacji, a przekład Biblii na niemiecki kształtuje język całego narodu.', '', 'ref'],
  // Later figures. An optional 7th field sets the letter shown in the circle.
  ['Św. Tomasz z Akwinu', 1265, 'Doktor Kościoła', 'Dominikanin i jeden z największych myślicieli w dziejach Kościoła, który w „Sumie teologicznej” pokazał, że wiara i rozum nie są rywalami, lecz prowadzą do tej samej prawdy. Gdy pisma Arystotelesa, przez wieki znane na Zachodzie tylko we fragmentach, powracają w przekładach z arabskiego i greckiego, Tomasz nie odrzuca ich z lękiem, lecz włącza w myśl chrześcijańską, tworząc syntezę, która do dziś kształtuje filozofię, etykę i prawo. Leon XIII polecił go jako mistrza dla szkół katolickich, a św. Jan Paweł II w encyklice „Fides et ratio” nazwał go wzorem dla wszystkich, którzy szukają prawdy.', '', 'chu', 'T'],
  ['Jan Gutenberg', 1455, 'Drukarz', 'Pierwszą wielką księgą drukowaną ruchomą czcionką jest Biblia: Jan Gutenberg wydaje ją w Moguncji ok. 1455 r., a piękno jej liter zachwyca do dziś. Słowo, przez wieki mozolnie przepisywane w klasztorach, zaczyna trafiać do tysięcy rąk, a do 1500 r. drukarnie działają już w setkach europejskich miast.', '', 'chu', 'G'],
  ['Kard. Stefan Wyszyński', 1948, 'Prymas Tysiąclecia', 'Prymas Polski, który przez ponad trzydzieści lat prowadzi Kościół przez czasy komunizmu, a uwięziony w latach 1953–1956, nie ugina się przed władzą. Wielką Nowenną przygotowuje naród do Tysiąclecia Chrztu Polski, a za niezłomność Polacy nazywają go Prymasem Tysiąclecia. W 2021 r. zostaje ogłoszony błogosławionym.', '', 'chu', 'W'],
  ['Św. Jan Paweł II', 1978, 'Papież', 'Karol Wojtyła z Wadowic, pierwszy papież Polak, który przez prawie 27 lat pontyfikatu niesie Ewangelię do ponad 120 krajów. Jego słowa z 1979 r. „Niech zstąpi Duch Twój! I odnowi oblicze ziemi. Tej ziemi!” dodały Polakom odwagi w drodze do wolności; od 2014 r. Kościół czci go jako świętego.', '', 'chu', 'J'],
  // Konstantyn to Tomasz z Akwinu
  ['Justynian I', 527, 'Cesarz bizantyjski', 'Dwa dzieła przetrwały jego panowanie o półtora tysiąca lat: uporządkowane prawo rzymskie, na którym wspiera się prawo Europy, i Hagia Sophia w Konstantynopolu, przez stulecia największa świątynia chrześcijaństwa. Według legendy cesarz Justynian, wchodząc do ukończonej świątyni, zawołał: „Salomonie, prześcignąłem cię!”.', '', 'jap', 'J'],
  ['Św. Grzegorz Wielki', 590, 'Papież', 'Rzymski patrycjusz, który porzuca wysokie urzędy dla klasztoru, a jako papież w czasach głodu i zarazy staje się ojcem ubogich i opiekunem Rzymu. Porządkuje liturgię, wysyła misjonarzy do Anglii i nazywa siebie „sługą sług Bożych”. Od jego imienia pochodzi nazwa chorału gregoriańskiego, a Kościół czci go jako Doktora.', '', 'chu', 'G'],
  ['Mahomet', 622, 'Założyciel islamu', 'Od roku 622 muzułmanie liczą swój kalendarz. Wtedy Mahomet, który od ok. 610 r. głosił w Mekce wiarę w jednego Boga, przenosi się ze zwolennikami do Medyny i tworzy tam pierwszą wspólnotę islamu. To wydarzenie nazywa się hidżrą.', '', 'sem', 'M'],
  ['Karol Wielki', 800, 'Cesarz', 'Król Franków, koronowany przez papieża Leona III na cesarza w Boże Narodzenie 800 r., który zjednoczył dużą część zachodniej Europy. Sprowadza na dwór uczonych, zakłada szkoły przy klasztorach i katedrach i każe przepisywać dawne księgi, ratując dla potomnych dziedzictwo starożytności. Ten rozkwit nazwano renesansem karolińskim.', '', 'jap', 'K'],
  ['Św. Cyryl i Metody', 863, 'Apostołowie Słowian', 'Bracia z Tesaloniki, którzy na prośbę księcia Rościsława przybywają na Morawy, by głosić Słowianom Ewangelię w ich własnym języku. Cyrylowi przypisuje się stworzenie pierwszego słowiańskiego pisma, głagolicy, a obaj bracia przekładają Pismo Święte i liturgię. Św. Jan Paweł II ogłosił ich w 1980 r. współpatronami Europy.', '', 'chu', 'C'],
  ['Mieszko I', 966, 'Książę Polan', 'Pierwszy historyczny władca Polski, który w 966 r. przyjmuje chrzest i wprowadza swój kraj do wspólnoty chrześcijańskiej Europy; od tej chwili liczy się dzieje państwa polskiego. Drogę do chrztu otworzyło mu małżeństwo z czeską księżniczką Dobrawą. Pod koniec życia oddał swoje państwo pod opiekę Stolicy Apostolskiej w dokumencie „Dagome iudex”.', '', 'chu', 'M'],
  ['Saladyn', 1187, 'Sułtan', 'Sułtan Egiptu i Syrii, który w 1187 r. odbija Jerozolimę z rąk krzyżowców. Nawet przeciwnicy cenili jego rycerskość, a w pokoju zawartym w 1192 r. z Ryszardem Lwie Serce pozwala chrześcijanom pielgrzymować do Jerozolimy.', '', 'sem', 'S'],
  // Marcin Luter to Wyszyński
  ['Krzysztof Kolumb', 1492, 'Żeglarz', 'Wyprawa, która miała odnaleźć zachodnią drogę do Azji, łączy dwa światy: w 1492 r. Krzysztof Kolumb, żeglujący pod banderą Hiszpanii, dociera do wysp Nowego Świata. Za odkrywcami idą misjonarze i Ewangelia dociera do obu Ameryk. Gdy zdobywcy krzywdzą rdzennych mieszkańców, w ich obronie staje dominikanin Bartłomiej de Las Casas.', '', 'jap', 'K'],
  ['Mikołaj Kopernik', 1543, 'Astronom', 'Kanonik warmiński, lekarz i astronom, który po latach obserwacji ukazuje w dziele „O obrotach sfer niebieskich” (1543) Ziemię krążącą wokół Słońca. Jak mówi znane powiedzenie, „wstrzymał Słońce, ruszył Ziemię”. Dzieło zadedykował papieżowi Pawłowi III, a jego model otworzył drogę nowożytnej astronomii.', '', 'jap', 'K'],
  ['Izaak Newton', 1687, 'Uczony', 'Angielski fizyk i matematyk, który w „Principiach” (1687) połączył niebo i ziemię jednym prawem powszechnego ciążenia: tym samym, które sprawia, że jabłko spada, a Księżyc krąży po swojej orbicie. Wpatrzony w ład kosmosu, w zakończeniu dzieła zapisał, że tak piękny układ Słońca, planet i komet mógł zrodzić się jedynie z zamysłu „istoty rozumnej i potężnej”.', '', 'jap', 'N'],
  ['Napoleon Bonaparte', 1804, 'Cesarz Francuzów', 'Z chaosu rewolucji wyłania się nie dawna monarchia, lecz władza jednego człowieka. W 1799 r. Napoleon ogłasza, że rewolucja „jest skończona”, a zarazem wpisuje jej ideały w prawo: Kodeks cywilny, zbudowany na zasadzie równości wobec prawa, wędruje wraz z jego armiami przez całą Europę i kształtuje ją po dziś dzień. W 1804 r., w katedrze Notre-Dame, sam wkłada sobie na głowę koronę cesarską. Ten, który konkordatem z 1801 r. przywrócił Francji publiczny kult, wkrótce przez pięć lat więzi papieża Piusa VII.', '', 'jap', 'N'],
  ['Leon XIII', 1891, 'Papież', 'Papież epoki przemysłowej, który w encyklice „Rerum novarum” (1891) staje po stronie robotników, upominając się o ich godność, sprawiedliwą płacę i prawo do zrzeszania się. Tym dokumentem daje początek nowożytnej katolickiej nauce społecznej, a wiele encyklik poświęca różańcowi, dlatego nazywany jest papieżem różańca.', '', 'chu', 'L'],
  // Greek philosophy and its heir in the Church
  ['Sokrates', -399, 'Filozof', 'Ateński myśliciel, który niczego nie spisał, a jednak zmienił bieg filozofii: w rozmowie, przez cierpliwe pytania, prowadzi rozmówców do poznania samych siebie i szukania prawdy o dobru. Skazany przez Ateńczyków na śmierć, wybiera wierność sumieniu zamiast ucieczki. Jego nauczanie przekazuje uczeń, Platon.', '', 'jap', 'S'],
  ['Platon', -387, 'Filozof', 'Uczeń Sokratesa i założyciel Akademii w Atenach, który uczy, że ponad zmiennym światem zjawisk istnieje wieczna prawda, dobro i piękno, a dusza człowieka jest nieśmiertelna. Jego myśl stanie się dla Ojców Kościoła, zwłaszcza dla św. Augustyna, językiem mówienia o Bogu.', '', 'jap', 'P'],
  ['Arystoteles', -335, 'Filozof', 'Uczeń Platona i wychowawca Aleksandra Wielkiego, założyciel Liceum, który porządkuje całą ówczesną wiedzę: tworzy logikę, etykę cnót i badanie przyrody, a rozumem dochodzi do Pierwszego Poruszyciela. Dzięki św. Tomaszowi z Akwinu staje się jednym z filarów myśli chrześcijańskiej.', '', 'jap', 'A'],
  ['Św. Augustyn', 397, 'Biskup Hippony, Doktor Kościoła', 'Po latach niespokojnych poszukiwań, wspierany wytrwałą modlitwą matki, św. Moniki, nawraca się i zostaje biskupem Hippony w Afryce. W „Wyznaniach” opowiada Bogu historię swojego serca słowami, które poruszają do dziś: „Stworzyłeś nas bowiem dla siebie i niespokojne jest serce nasze, dopóki nie spocznie w Tobie”. Jako Doktor Kościoła łączy wiarę z myślą Platona i kształtuje teologię całego Zachodu.', '', 'chu', 'A'],
  // The first university; the chart marks the age of science on the outer rim from here.
  ['Uniwersytet Boloński', 1088, 'Pierwszy uniwersytet', 'Najstarszy nieprzerwanie działający uniwersytet świata, który według tradycji powstał w 1088 r. i zasłynął studiami prawa rzymskiego i kanonicznego. Jego śladem, często ze szkół katedralnych i pod opieką papieży, rodzą się uniwersytety w Paryżu, Oksfordzie i Krakowie (1364): wspólnoty mistrzów i uczniów, w których rozkwitają teologia, prawo, medycyna i nauki o przyrodzie.', '', 'chu', 'U']
];
